+.nav{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: 16px;
+  padding: 14px 0;
+}
+
+.brand{
+  display:flex;
+  align-items:center;
+  gap: 10px;
+  min-width: 170px;
+}
+.logo{
+  width: 32px;
+  height: 32px;
+  border-radius: 10px;
