+.brand-title{font-weight: 760; letter-spacing: -.02em}
+.brand-sub{display:block; font-size: 12px; color: var(--muted); margin-top: -2px}
+
+.nav-left,.nav-right{display:flex; align-items:center; gap: 10px}
+.nav-links{display:flex; align-items:center; gap: 4px}
+
+.nav-link{
+  display:inline-flex;
+  align-items:center;
+  gap: 8px;
+  padding: 10px 10px;
+  border-radius: 12px;
+  color: rgba(11, 15, 25, .86);
+  font-weight: 600;
+  font-size: 14px;
+}
+.nav-link:hover{background: rgba(17, 24, 39, .05)}
+
+.nav-link .chev{width: 14px; height:14px; opacity:.7}
+
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap: 8px;
+  padding: 10px 12px;
+  border-radius: 12px;
+  border: 1px solid var(--border);
+  background: var(--surface);
+  font-weight: 650;
+  font-size: 14px;
+  cursor:pointer;
+  transition: transform .12s ease, box-shadow .12s ease, background .12s ease, border-color .12s ease;
