+.btn:hover{transform: translateY(-1px); box-shadow: var(--shadow-sm)}
+.btn.primary{border-color: rgba(0,114,245,.35); background: var(--accent); color:#fff}
+.btn.primary:hover{background: var(--accent-2)}
+.btn.ghost{background: transparent}
+.btn.small{padding: 8px 10px; border-radius: 12px; font-size: 13px}
+
+.kbd{
+  font-family: var(--mono);
+  font-size: 12px;
+  color: rgba(255,255,255,.85);
+  background: rgba(0,0,0,.16);
+  border: 1px solid rgba(255,255,255,.18);
+  padding: 2px 6px;
+  border-radius: 8px;
+}
+
+.nav-right .btn.primary{padding: 10px 14px}
+
+.mobile-toggle{display:none}
+
+/* Mega menu */
+.menu-wrap{position:relative}
+.menu-panel{
+  position:absolute;
+  left: 0;
+  top: calc(100% + 10px);
+  width: min(820px, calc(100vw - 40px));
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: 18px;
+  box-shadow: var(--shadow);
+  padding: 16px;
+  display:none;
+}
+.menu-panel.open{display:block; animation: pop .14s ease-out}
+@keyframes pop{from{opacity:0; transform: translateY(-6px)} to{opacity:1; transform: translateY(0)}}
+
+.menu-grid{display:grid; grid-template-columns: 1.15fr 1.15fr .9fr; gap: 14px}
+.menu-col{border: 1px solid var(--border); border-radius: 14px; padding: 14px; background: linear-gradient(180deg, rgba(245,247,251,.65), rgba(255,255,255,1))}
+.menu-title{font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: var(--muted); margin: 0 0 10px}
+.menu-item{display:flex; flex-direction:column; gap: 2px; padding: 10px 10px; border-radius: 12px}
+.menu-item:hover{background: rgba(0,114,245,.06)}
+.menu-item .name{font-weight: 700; font-size: 14px}
+.menu-item .desc{font-size: 12.5px; color: var(--muted)}
+
+.menu-panel.resources{width: min(720px, calc(100vw - 40px))}
+.resources-grid{display:grid; grid-template-columns: 1fr 1fr 1fr; gap: 14px}
+
+/* Hero */
+.hero{padding: 30px 0 18px}
+.hero-top{display:flex; align-items:flex-end; justify-content:space-between; gap: 18px; flex-wrap: wrap}
+.hero h1{margin: 0; font-size: clamp(30px, 4vw, 42px); letter-spacing: -.03em; line-height: 1.12}
+.hero p{margin: 10px 0 0; color: var(--muted); max-width: 68ch}
+
+.hero-meta{
+  display:flex;
+  gap: 10px;
+  align-items:center;
+  flex-wrap: wrap;
+}
+.chip{
+  display:inline-flex;
+  align-items:center;
+  gap: 8px;
+  border: 1px solid var(--border);
+  background: var(--surface);
+  border-radius: 999px;
+  padding: 8px 10px;
+  font-size: 13px;
+  color: rgba(11,15,25,.82);
+}
+.dot{width: 9px; height: 9px; border-radius: 999px; background: var(--accent)}
+
+/* Filters */
+.filters{
+  padding: 14px 0 8px;
+}
+.filters-bar{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: 12px;
+  flex-wrap: wrap;
+}
+.pills{display:flex; gap: 8px; align-items:center; flex-wrap: wrap}
+.pill{
+  border: 1px solid var(--border);
+  background: var(--surface);
+  padding: 8px 11px;
+  border-radius: 999px;
+  font-weight: 650;
+  font-size: 13px;
+  color: rgba(11,15,25,.84);
+  cursor:pointer;
+  transition: transform .12s ease, background .12s ease, border-color .12s ease;
+}
+.pill:hover{transform: translateY(-1px)}
+.pill.active{background: rgba(0,114,245,.10); border-color: rgba(0,114,245,.35); color: rgba(11,76,203,.98)}
+
+.search{
+  display:flex;
+  align-items:center;
+  gap: 10px;
+  padding: 10px 12px;
+  border: 1px solid var(--border);
+  background: var(--surface);
+  border-radius: 14px;
+  min-width: min(420px, 100%);
+}
+.search svg{width: 18px; height:18px; opacity:.62}
+.search input{
+  width:100%;
+  border: none;
+  outline:none;
+  background: transparent;
+  font-size: 14px;
+  color: var(--text);
+}
+.search .hint{color: var(--muted-2); font-size: 12px; font-family: var(--mono)}
+
+/* Featured */
+.section{padding: 18px 0}
+.section-title{display:flex; align-items:flex-end; justify-content:space-between; gap: 12px; margin-bottom: 14px}
+.section-title h2{margin:0; font-size: 18px; letter-spacing: -.01em}
+.section-title p{margin:0; color: var(--muted); font-size: 13px}
+
+.featured-grid{
+  display:grid;
+  grid-template-columns: 1.2fr .9fr .9fr;
+  gap: 14px;
+}
+.featured-card{
+  position:relative;
+  border-radius: 20px;
+  border: 1px solid var(--border);
+  background: radial-gradient(120% 140% at 20% 0%, rgba(0,114,245,.12), rgba(255,255,255,1));
+  box-shadow: var(--shadow-sm);
+  overflow:hidden;
+  transition: transform .14s ease, box-shadow .14s ease, border-color .14s ease;
+}
+.featured-card:hover{transform: translateY(-2px); box-shadow: var(--shadow); border-color: rgba(0,114,245,.22)}
+.featured-card .inner{padding: 18px}
+.featured-card .kicker{display:flex; justify-content:space-between; gap: 12px; align-items:center; color: var(--muted); font-size: 12.5px}
+.tag{
+  display:inline-flex;
+  align-items:center;
+  gap: 6px;
+  padding: 6px 10px;
+  border-radius: 999px;
+  background: rgba(0,114,245,.10);
+  color: rgba(11,76,203,.98);
+  border: 1px solid rgba(0,114,245,.20);
+  font-weight: 700;
+  font-size: 12px;
+}
+.title{margin: 10px 0 8px; font-size: 18px; line-height: 1.22; letter-spacing: -.02em}
+.featured-card.featured-hero .title{font-size: 22px}
+.excerpt{margin:0; color: rgba(11,15,25,.78); font-size: 14px}
+
+.meta{
+  margin-top: 14px;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: 12px;
+}
+.author{display:flex; align-items:center; gap: 10px; min-width: 0}
+.avatar{
+  width: 28px; height: 28px; border-radius: 999px;
+  background: linear-gradient(180deg, rgba(17,24,39,.20), rgba(17,24,39,.06));
+  border: 1px solid rgba(17,24,39,.16);
+}
+.author .name{font-weight: 700; font-size: 13px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width: 200px}
+.author .role{font-size: 12px; color: var(--muted); margin-top: -2px}
+
+.stats{
+  display:flex;
+  flex-wrap: wrap;
+  gap: 8px;
+  margin-top: 12px;
+}
+.stat{
+  border: 1px solid rgba(0,114,245,.18);
+  background: rgba(0,114,245,.06);
+  border-radius: 999px;
+  padding: 6px 10px;
+  font-size: 12px;
+  color: rgba(11,76,203,.95);
+  font-weight: 700;
+}
+
+/* Latest grid */
+.grid{
+  display:grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 14px;
+}
+.card{
+  border-radius: var(--radius);
+  background: var(--surface);
+  border: 1px solid var(--border);
+  box-shadow: 0 1px 0 rgba(11,15,25,.03);
+  overflow:hidden;
+  transition: transform .14s ease, box-shadow .14s ease, border-color .14s ease;
+}
+.card:hover{transform: translateY(-2px); box-shadow: var(--shadow-sm); border-color: rgba(0,114,245,.18)}
+.card .pad{padding: 16px}
+.card .kicker{display:flex; align-items:center; justify-content:space-between; gap: 12px; color: var(--muted); font-size: 12.5px}
+.card .title{font-size: 16px; margin: 10px 0 8px}
+.card .excerpt{font-size: 13.5px}
+.card .meta{margin-top: 14px}
+
+.no-results{
+  border: 1px dashed rgba(17,24,39,.22);
+  background: rgba(245,247,251,.55);
+  padding: 18px;
+  border-radius: 18px;
+  color: var(--muted);
+  display:none;
+}
+.no-results.open{display:block}
+
+.show-more{
+  display:flex;
+  justify-content:center;
+  margin-top: 16px;
+}
+
+/* CTA */
+.cta{
+  margin-top: 8px;
+  border-radius: 22px;
+  border: 1px solid rgba(0,114,245,.20);
+  background:
+    radial-gradient(120% 120% at 0% 0%, rgba(0,114,245,.18), rgba(255,255,255,1)),
+    linear-gradient(180deg, rgba(245,247,251,.4), rgba(255,255,255,1));
+  padding: 22px;
+  display:grid;
+  grid-template-columns: 1.2fr .8fr;
+  gap: 16px;
+  align-items:center;
+}
+.cta h3{margin:0; font-size: 20px; letter-spacing: -.02em; line-height: 1.2}
+.cta p{margin: 10px 0 0; color: var(--muted)}
+.cta-actions{display:flex; flex-wrap: wrap; gap: 10px; justify-content:flex-end}
+
+.enterprise{
+  margin-top: 14px;
+  border-radius: 18px;
+  border: 1px solid var(--border);
+  background: var(--surface);
+  padding: 16px;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: 12px;
+}
+.enterprise strong{display:block}
+.enterprise span{display:block; color: var(--muted); font-size: 13px; margin-top: 2px}
+
+/* Footer */
+footer{
+  margin-top: 26px;
+  padding: 26px 0;
+  border-top: 1px solid var(--border);
+  background: #fff;
+}
+.footer-grid{display:grid; grid-template-columns: repeat(4, 1fr); gap: 14px}
+.footer-col{padding: 10px 0}
+.footer-title{margin:0 0 10px; font-size: 12px; text-transform: uppercase; letter-spacing: .10em; color: var(--muted)}
+.footer-col a{display:block; padding: 6px 0; color: rgba(11,15,25,.82); font-size: 13.5px}
+.footer-col a:hover{color: rgba(11,76,203,.98)}
+
+.footer-bottom{
+  display:flex;
+  justify-content:space-between;
+  align-items:center;
+  gap: 12px;
+  flex-wrap: wrap;
+  margin-top: 16px;
+  padding-top: 16px;
+  border-top: 1px solid var(--border);
+  color: var(--muted);
+  font-size: 13px;
+}
+.status{
+  display:flex;
+  align-items:center;
+  gap: 10px;
+}
+.status .dot{background: #16A34A}
+
+/* Responsive */
+@media (max-width: 980px){
+  .featured-grid{grid-template-columns: 1fr;}
+  .grid{grid-template-columns: repeat(2, 1fr)}
+  .cta{grid-template-columns: 1fr}
+  .cta-actions{justify-content:flex-start}
+  .footer-grid{grid-template-columns: repeat(2, 1fr)}
+}
+@media (max-width: 680px){
+  .nav-links,.nav-right .btn.ghost{display:none}
+  .mobile-toggle{display:inline-flex}
+  .grid{grid-template-columns: 1fr}
+  .search{min-width: 100%}
+}
+
+/* Mobile menu */
+.mobile-panel{
+  display:none;
+  padding: 8px 0 14px;
+}
+.mobile-panel.open{display:block}
+.mobile-panel .row{display:flex; flex-wrap: wrap; gap: 8px}
+.mobile-panel a{border:1px solid var(--border); background: var(--surface); padding: 10px 12px; border-radius: 12px; font-weight: 650; font-size: 14px}
+.mobile-panel a:hover{border-color: rgba(0,114,245,.18)}
+
*** End Patch
PATCH

